package main

import (
	"encoding/json"
	"fmt"
)

func describe(v any) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case bool:
		return fmt.Sprintf("bool(%t)", x)
	case float64:
		return fmt.Sprintf("son(%g)", x)
	case string:
		return fmt.Sprintf("satr(%q)", x)
	case []any:
		return fmt.Sprintf("massiv(%d ta element)", len(x))
	case map[string]any:
		return fmt.Sprintf("obyekt(%d ta kalit)", len(x))
	default:
		return "noma'lum"
	}
}

func main() {
	var items []any
	json.Unmarshal([]byte(`[null, true, 7.5, "salom", [1, 2], {"a": 1}]`), &items)
	for _, it := range items {
		fmt.Println(describe(it))
	}
}

