package main

import (
	"encoding/json"
	"errors"
	"fmt"
)

type Input struct {
	Age int `json:"age"`
}

func parse(raw string) error {
	var in Input
	err := json.Unmarshal([]byte(raw), &in)

	var syn *json.SyntaxError
	var typ *json.UnmarshalTypeError
	switch {
	case err == nil:
		fmt.Println("OK, yosh:", in.Age)
	case errors.As(err, &syn):
		fmt.Printf("JSON buzuq (%d-baytda)\n", syn.Offset)
	case errors.As(err, &typ):
		fmt.Printf("%q maydoni noto'g'ri: %s kelgan, %s kutilgan\n", typ.Field, typ.Value, typ.Type)
	default:
		fmt.Println("boshqa xato:", err)
	}
	return err
}

func main() {
	parse(`{"age": 30}`)
	parse(`{"age": 30`)
	parse(`{"age": "o'ttiz"}`)
	parse(`{"age": 30.5}`)
}

