package main

import (
	"encoding/json"
	"fmt"
	"time"
)

type Server struct {
	Host    string
	Port    int
	TLS     bool
	Timeout int
}

type Config struct {
	AppName string
	Servers []Server
}

const raw = `{
    "AppName": "recipes",
    "Servers": [
        {"Host": "10.0.0.1", "Port": 8080, "TLS": false, "Timeout": 5},
        {"Host": "10.0.0.2", "Port": 8443, "TLS": true,  "Timeout": 10}
    ]
}`

func main() {
	var cfg Config
	if err := json.Unmarshal([]byte(raw), &cfg); err != nil {
		fmt.Println("konfiguratsiya xato:", err)
		return
	}
	fmt.Println("ilova:", cfg.AppName)
	for _, s := range cfg.Servers {
		scheme := "http"
		if s.TLS {
			scheme = "https"
		}
		fmt.Printf("%s://%s:%d (kutish %v)\n", scheme, s.Host, s.Port, time.Duration(s.Timeout)*time.Second)
	}
}

