import (
	"encoding/json"
	"fmt"
	"sort"
)

func walk(path string, v any) {
	switch x := v.(type) {
	case map[string]any:
		keys := make([]string, 0, len(x))
		for k := range x {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			walk(path+"."+k, x[k])
		}
	case []any:
		for i, item := range x {
			walk(fmt.Sprintf("%s[%d]", path, i), item)
		}
	default:
		fmt.Printf("%s = %v\n", path, x)
	}
}

