}

func parse(body string) (CreateUser, error) {
	dec := json.NewDecoder(strings.NewReader(body))
	dec.DisallowUnknownFields()

	var u CreateUser
	err := dec.Decode(&u)
	if err != nil {
		if after, found := strings.CutPrefix(err.Error(), "json: unknown field "); found {
			return u, fmt.Errorf("noma'lum maydon: %s", after)
		}
		return u, fmt.Errorf("noto'g'ri so'rov: %w", err)
	}
	return u, nil
}

