import (
	"encoding/json"
	"fmt"
	"math"
)

type Shape interface{ Area() float64 }

type Circle struct{ R float64 }
type Rect struct{ W, H float64 }

func (c Circle) Area() float64 { return math.Pi * c.R * c.R }
func (r Rect) Area() float64   { return r.W * r.H }

type ShapeWrapper struct{ Shape }

func (s *ShapeWrapper) UnmarshalJSON(b []byte) error {
	var head struct {
		Type string          `json:"type"`
		Data json.RawMessage `json:"data"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return err
	}
	switch head.Type {
	case "circle":
		var c Circle
		if err := json.Unmarshal(head.Data, &c); err != nil {
			return err
		}
		s.Shape = c
	case "rect":
		var r Rect
		if err := json.Unmarshal(head.Data, &r); err != nil {
			return err
		}
		s.Shape = r
	default:
		return fmt.Errorf("noma'lum shakl turi: %q", head.Type)
	}
	return nil
}

func main() {
	input := `[
        {"type":"circle","data":{"R":2}},
        {"type":"rect","data":{"W":3,"H":4}}
    ]`
	var shapes []ShapeWrapper
	if err := json.Unmarshal([]byte(input), &shapes); err != nil {
		fmt.Println(err)
		return
	}
	for _, s := range shapes {
		fmt.Printf("%T maydoni: %.2f\n", s.Shape, s.Area())
	}

	err := json.Unmarshal([]byte(`[{"type":"uchburchak","data":{}}]`), &shapes)
	fmt.Println(err)
}

