	dec.Token()
	var count, total, max int
	for dec.More() {
		var s Sale
		dec.Decode(&s)
		count++
		total += s.Amount
		if s.Amount > max {
			max = s.Amount
		}
	}
	dec.Token()
	fmt.Println("elementlar:", count, "| jami:", total, "| eng katta:", max)
}

