import (
	"encoding/json/jsontext"
	"fmt"

	jsonv2 "encoding/json/v2"
)

type Point struct{ X, Y int }

func (p Point) MarshalJSONTo(enc *jsontext.Encoder) error {
	if err := enc.WriteToken(jsontext.BeginArray); err != nil {
		return err
	}
	enc.WriteToken(jsontext.Int(int64(p.X)))
	enc.WriteToken(jsontext.Int(int64(p.Y)))
	return enc.WriteToken(jsontext.EndArray)
}

func (p *Point) UnmarshalJSONFrom(dec *jsontext.Decoder) error {
	var xy [2]int
	if err := jsonv2.UnmarshalDecode(dec, &xy); err != nil {
		return err
	}
	p.X, p.Y = xy[0], xy[1]
	return nil
}

func main() {
	route := map[string][]Point{"yo'l": {{0, 0}, {3, 4}, {6, 8}}}
	data, _ := jsonv2.Marshal(route)
	fmt.Println(string(data))

	var back map[string][]Point
	err := jsonv2.Unmarshal([]byte(`{"a":[[1,2],[3,4]]}`), &back)
	fmt.Println(back, err)

	err = jsonv2.Unmarshal([]byte(`{"a":[[1,2,3]]}`), &back)
	fmt.Println(err != nil)
}

package main

import (
	"fmt"
	"time"

	jsonv2 "encoding/json/v2"
)

type Meeting struct {
	Title string        `json:"title"`
	At    time.Time     `json:"at"`
	Len   time.Duration `json:"len"`
}

func main() {
	m := Meeting{
		Title: "Rejalashtirish",
		At:    time.Date(2026, 10, 18, 9, 30, 0, 0, time.UTC),
		Len:   90 * time.Minute,
	}

	marshalers := jsonv2.JoinMarshalers(
		jsonv2.MarshalFunc(func(t time.Time) ([]byte, error) {
			return jsonv2.Marshal(t.Format("02.01.2006 15:04"))
		}),
		jsonv2.MarshalFunc(func(d time.Duration) ([]byte, error) {
			return jsonv2.Marshal(d.String())
		}),
	)

	data, err := jsonv2.Marshal(m, jsonv2.WithMarshalers(marshalers))
	fmt.Println(string(data), err)

	_, err = jsonv2.Marshal(m)
	fmt.Println("funksiyasiz:", err != nil)
}

package main

import (
	"encoding/json"
	"encoding/json/jsontext"
	"errors"
	"fmt"

	jsonv2 "encoding/json/v2"
)

func main() {
	in := []byte(`{"id": 12345678901234567890, "ball": 4.50, "nom": "x"}`)

	var plain any
	jsonv2.Unmarshal(in, &plain)
	fmt.Println("oddiy:", plain)

	keepNumbers := jsonv2.UnmarshalFromFunc(func(dec *jsontext.Decoder, v *any) error {
		if dec.PeekKind() != '0' {
			return errors.ErrUnsupported // boshqa turlar odatdagidek
		}
		raw, err := dec.ReadValue()
		if err != nil {
			return err
		}
		*v = json.Number(raw)
		return nil
	})

	var exact any
	err := jsonv2.Unmarshal(in, &exact, jsonv2.WithUnmarshalers(keepNumbers))
	fmt.Println("aniq: ", exact, err)
	fmt.Printf("id tipi: %T\n", exact.(map[string]any)["id"])
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"

	jsonv2 "encoding/json/v2"
)

type Cart struct {
	Items []struct {
		SKU string `json:"sku"`
		Qty int    `json:"qty"`
	} `json:"items"`
}

func main() {
	in := []byte(`{"items":[{"sku":"A","qty":1},{"sku":"B","qty":"ko'p"}]}`)

	var c1 Cart
	err := json.Unmarshal(in, &c1)
	var ute *json.UnmarshalTypeError
	if errors.As(err, &ute) {
		fmt.Println("v1 Field:", ute.Field, "| Value:", ute.Value, "| Type:", ute.Type)
	}

	var c2 Cart
	err = jsonv2.Unmarshal(in, &c2)
	var se *jsonv2.SemanticError
	if errors.As(err, &se) {
		fmt.Println("v2 Pointer:", se.JSONPointer)
		fmt.Println("v2 JSONKind:", se.JSONKind, "| GoType:", se.GoType)
	}
}
